//! Reconstructed native regression sources. NOT executed in the recovered cloud.
use super::*;
use crate::core::{gc::{Context,RootSet},object::{NIL,ObjectType,Symbol},cons::Cons};
use rune_core::macros::root;
fn ht(o:Object<'_>)->&LispHashTable{let ObjectType::HashTable(t)=o.untag()else{unreachable!()};t}
#[test]fn strategy_and_identity_keys_rehash_after_moving_gc(){for test in [HashTableTest::Eq,HashTableTest::Eql,HashTableTest::Equal]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test(test)),cx);root!(a,cx.add("same"),cx);root!(b,cx.add("same"),cx);ht(table.bind(cx)).insert(a.bind(cx),cx.add(1)).unwrap();ht(table.bind(cx)).insert(b.bind(cx),cx.add(2)).unwrap();for _ in 0..3{cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).test(),test);assert_eq!(ht(table.bind(cx)).len(),if test==HashTableTest::Equal{1}else{2});assert_eq!(ht(table.bind(cx)).get(a.bind(cx)).unwrap().unwrap(),cx.add(if test==HashTableTest::Equal{2}else{1}));}}}
#[test]fn numeric_modes_preserve_nan_bits_signed_zero_and_bigint_values(){for test in [HashTableTest::Eq,HashTableTest::Eql,HashTableTest::Equal]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test(test)),cx);let nan=f64::from_bits(0x7ff8_0000_0000_0123);root!(a,cx.add(nan),cx);root!(b,cx.add(nan),cx);ht(table.bind(cx)).insert(a.bind(cx),cx.add(1)).unwrap();ht(table.bind(cx)).insert(b.bind(cx),cx.add(2)).unwrap();let n:num_bigint::BigInt=(num_bigint::BigInt::from(1)<<100usize)+7;root!(x,cx.add(n.clone()),cx);root!(y,cx.add(n),cx);ht(table.bind(cx)).insert(x.bind(cx),cx.add(3)).unwrap();ht(table.bind(cx)).insert(y.bind(cx),cx.add(4)).unwrap();ht(table.bind(cx)).insert(cx.add(0.0),NIL).unwrap();ht(table.bind(cx)).insert(cx.add(-0.0),NIL).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),if test==HashTableTest::Eq{6}else{4});assert_eq!(ht(table.bind(cx)).get(a.bind(cx)).unwrap().unwrap(),cx.add(if test==HashTableTest::Eq{1}else{2}));assert_eq!(ht(table.bind(cx)).get(x.bind(cx)).unwrap().unwrap(),cx.add(if test==HashTableTest::Eq{3}else{4}));}}
#[test]fn equal_text_and_raw_bytes_share_ascii_only(){let roots=RootSet::default();let cx=&Context::new(&roots);let t=cx.add(HashTable::with_test(HashTableTest::Equal));ht(t).insert(cx.add("a"),cx.add(7)).unwrap();assert_eq!(ht(t).get(cx.add(vec![b'a'])).unwrap().unwrap(),cx.add(7));ht(t).insert(cx.add("ÿ"),cx.add(8)).unwrap();assert!(ht(t).get(cx.add(vec![255u8])).unwrap().is_none());let a=cx.add(vec![Object::from(cx.add("a"))]);let b=cx.add(vec![Object::from(cx.add(vec![b'a']))]);ht(t).insert(a,cx.add(9)).unwrap();assert_eq!(ht(t).get(b).unwrap().unwrap(),cx.add(9));}
#[test]fn identity_cycles_move_and_resident_equal_cycles_fail_closed(){for test in [HashTableTest::Eq,HashTableTest::Eql]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test(test)),cx);root!(key,cx.add(vec![NIL]),cx);let ObjectType::Vec(v)=key.bind(cx).untag()else{unreachable!()};v.try_mut().unwrap()[0].set(key.bind(cx));ht(table.bind(cx)).insert(key.bind(cx),cx.add(7)).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).get(key.bind(cx)).unwrap().unwrap(),cx.add(7));}let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::default()),cx);root!(key,Cons::new(NIL,NIL,cx),cx);ht(table.bind(cx)).insert(key.bind(cx).into(),cx.add(7)).unwrap();key.bind(cx).set_cdr(key.bind(cx).into()).unwrap();cx.garbage_collect(true);assert!(ht(table.bind(cx)).get(NIL).is_err());assert!(ht(table.bind(cx)).insert(NIL,NIL).is_err());key.bind(cx).set_cdr(NIL).unwrap();assert_eq!(ht(table.bind(cx)).get(key.bind(cx).into()).unwrap().unwrap(),cx.add(7));}
#[test]fn foreign_copy_preserves_test_or_rejects_transitive_identity_changes(){let roots=RootSet::default();let cx=&Context::new(&roots);let mut t=HashTable::with_test(HashTableTest::Eql);t.insert(cx.add(7),cx.add(8)).unwrap();let t=cx.add(t);let copied=ht(t).clone_in(&cx.block).unwrap();assert_eq!(copied.untag().test(),HashTableTest::Eql);assert_eq!(copied.untag().get(cx.add(7)).unwrap().unwrap(),cx.add(8));let inner=cx.add(HashTable::default());let key=cx.add(vec![Object::from(inner)]);let t=cx.add(HashTable::default());ht(t).insert(key,NIL).unwrap();assert!(ht(t).clone_in(&cx.block).is_err());let symbol=Symbol::new_uninterned("identity-key",&cx.block);let t=cx.add(HashTable::default());ht(t).insert(cx.add(vec![Object::from(symbol)]),NIL).unwrap();assert!(ht(t).clone_in(&cx.block).is_err());}
